import openpyxl
wb=openpyxl.load_workbook("documents/oakridge-employee-census.xlsx")
for ws in wb:
  print("==",ws.title, ws.dimensions)
  for r in ws.iter_rows(values_only=True):
    if any(c is not None for c in r): print(r)
  # comments
  for row in ws.iter_rows():
    for c in row:
      if c.comment: print("COMMENT",c.coordinate,c.comment.text)
